package main

import (
    "context"
    "errors"
    "testing"
)

func TestRefreshSession(t *testing.T) {
    for _, status := range []int{200, 401, 503} {
        t.Run(httpStatus(status), func(t *testing.T) {
            withProvider(t, status)
            err := refreshSession(context.Background(), "valid-token")
            if (err != nil) != (status != 200) {
                t.Fatalf("status %d: unexpected error %v", status, err)
            }
        })
    }
}

func TestRefreshSessionCanceled(t *testing.T) {
    ctx, cancel := context.WithCancel(context.Background())
    cancel()
    err := refreshSession(ctx, "valid-token")
    if !errors.Is(err, context.Canceled) {
        t.Fatalf("want cancellation, got %v", err)
    }
}

